const TONES = new Set(['ok', 'warn', 'bad', 'info', 'muted']);

/**
 * Status badge. Map your domain's states to a tone at the call site.
 *
 * @param {string} label
 * @param {'ok' | 'warn' | 'bad' | 'info' | 'muted'} [tone]
 * @returns {string}
